// src/pages/LoaderPage.js
import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './LoaderPage.css'; // Move all CSS here

function LoaderPage() {
  const [dotCount, setDotCount] = useState(0);
  const [fadeOut, setFadeOut] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Animate dots
    const dotInterval = setInterval(() => {
      setDotCount(prev => (prev + 1) % 4);
    }, 500);

    // Load for 3 seconds then fade out & redirect
    const timeout = setTimeout(() => {
      clearInterval(dotInterval);
      setFadeOut(true);

      // Redirect after fade out
      setTimeout(() => {
        navigate('/home'); // Change to your home page route
      }, 500);
    }, 3000);

    return () => {
      clearInterval(dotInterval);
      clearTimeout(timeout);
    };
  }, [navigate]);

  return (
    <div className={`loader-container ${fadeOut ? 'fade-out' : ''}`}>
      <div className="logo">🕺🏽</div>
      <h1>My dancing Journey</h1>
      <div className="spinner"></div>
      <div className="loading-text">
        Loading<span className="dots">{'.'.repeat(dotCount)}</span>
      </div>
    </div>
  );
}

export default LoaderPage;
